rules.fullRuleBlock:
def("삼각비", "01", "삼각비의 값", SEC.뜻, "기본", (rng) => {
    const [p, q, r] = pick(rng, TRIPLES);
    const mode = intBetween(rng, 0, 2);
    // $\angle B=90^\circ$ — $\overline{BC}$ 가 $\angle A$ 의 대변, $\overline{AB}$ 가 이웃변.
    // mode 2($\tan A=\overline{BC}/\overline{AB}$)는 진분수여야 하므로 대변을 짧게 고정한다.
    const swap = mode === 2 ? false : rng() < 0.5;
    const bc = swap ? q : p;
    const ab = swap ? p : q;
    const [num, den] = red(mode === 1 ? ab : bc, mode === 2 ? ab : r);
    const asked = trigOf(mode, "A");
    const ratio = [
      `\\dfrac{\\overline{BC}}{\\overline{AC}}`,
      `\\dfrac{\\overline{AB}}{\\overline{AC}}`,
      `\\dfrac{\\overline{BC}}{\\overline{AB}}`,
    ][mode]!;
    const raw = [
      `\\dfrac{${bc}}{${r}}`,
      `\\dfrac{${ab}}{${r}}`,
      `\\dfrac{${bc}}{${ab}}`,
    ][mode]!;
    return {
      content: `직각삼각형 $ABC$에서 $\\angle B=90^\\circ$이고 $\\overline{AB}=${cm(ab)}$, $\\overline{BC}=${cm(bc)}$일 때, $${asked}$의 값을 구하시오.`,
      answer: `$${frac(num, den)}$`,
      solution: `피타고라스 정리에서 $\\overline{AC}=\\sqrt{${ab}^2+${bc}^2}=${r}\\,(\\mathrm{cm})$이다.\n따라서 $${asked}=${ratio}=${raw === frac(num, den) ? raw : `${raw}=${frac(num, den)}`}$이다.`,
      facts: { ab, bc, ac: r, mode, num, den },
      figureSpec: figRight({
        vert: ab,
        horz: bc,
        dims: { AB: dimCm(ab), BC: dimCm(bc) },
      }),
    };
  }),

def(
    "삼각비",
    "02",
    "삼각비를 이용하여 삼각형의 변의 길이 구하기",
    SEC.뜻,
    "기본",
    (rng) =>
      attempt(120, () => {
        const [p, q, r] = pick(rng, TRIPLES);
        const mode = intBetween(rng, 0, 2);
        const t = intBetween(rng, 1, 4);
        // $\angle B=90^\circ$ · $\angle A$ 기준: 대변 $pt$, 이웃변 $qt$, 빗변 $rt$.
        const opp = p * t;
        const adj = q * t;
        const hyp = r * t;
        if (hyp > 80) return null;
        const [gnum, gden] = red(mode === 1 ? q : p, mode === 2 ? q : r);
        if (gnum >= gden) return null;
        const given = mode === 2 ? adj : hyp;
        const x = mode === 1 ? adj : opp;
        const givenSide = mode === 2 ? SIDE_NAMES[0]! : SIDE_NAMES[2]!;
        const askSide = mode === 1 ? SIDE_NAMES[0]! : SIDE_NAMES[1]!;
        const relation = [
          `\\sin A=\\dfrac{\\overline{BC}}{\\overline{AC}}`,
          `\\cos A=\\dfrac{\\overline{AB}}{\\overline{AC}}`,
          `\\tan A=\\dfrac{\\overline{BC}}{\\overline{AB}}`,
        ][mode]!;
        return {
          content: `직각삼각형 $ABC$에서 $\\angle B=90^\\circ$이고 $${trigOf(mode, "A")}=${frac(gnum, gden)}$, $${givenSide}=${cm(given)}$일 때, $${askSide}$의 길이를 구하시오.`,
          answer: `$${cm(x)}$`,
          solution: `$${relation}$이다.\n따라서 $${askSide}=${given}\\times${frac(gnum, gden)}=${x}\\,(\\mathrm{cm})$이다.`,
          facts: { num: gnum, den: gden, given, x, mode },
          figureSpec: figRight({
            vert: adj,
            horz: opp,
            dims: mode === 2 ? { AB: dimCm(given) } : { CA: dimCm(given) },
          }),
        };
      }),
  ),

def(
    "삼각비",
    "03",
    "한 삼각비의 값을 알 때 다른 삼각비의 값 구하기",
    SEC.뜻,
    "응용",
    (rng) =>
      attempt(120, () => {
        // 세 쌍을 **기약으로** 줄인다 — 안 그러면 발문의 `tan A=3/4` 와 해설의
        // 「밑변 16, 높이 12」가 따로 논다(같은 값인데 학생은 딴 삼각형으로 읽는다).
        const [p0, q0, r0] = pick(rng, TRIPLES);
        const g0 = gcd(gcd(p0, q0), r0);
        const [p, q, r] = [p0 / g0, q0 / g0, r0 / g0];
        const given = intBetween(rng, 0, 2);
        const want = intBetween(rng, 0, 2);
        if (given === want) return null;
        // $\tan$ 은 «대변/이웃변»이라 진분수가 아니면 지면에서 대분수가 된다.
        if ((given === 2 || want === 2) && p >= q) return null;
        const pair = (fn: number): [number, number] =>
          fn === 0 ? red(p, r) : fn === 1 ? red(q, r) : red(p, q);
        const [gn, gd] = pair(given);
        const [wn, wd] = pair(want);
        const legText =
          given === 0
            ? `빗변의 길이가 $${r}$, 높이가 $${p}$인 직각삼각형에서 밑변의 길이는 $\\sqrt{${r}^2-${p}^2}=${q}$`
            : given === 1
              ? `빗변의 길이가 $${r}$, 밑변의 길이가 $${q}$인 직각삼각형에서 높이는 $\\sqrt{${r}^2-${q}^2}=${p}$`
              : `밑변의 길이가 $${q}$, 높이가 $${p}$인 직각삼각형에서 빗변의 길이는 $\\sqrt{${p}^2+${q}^2}=${r}$`;
        return {
          content: `$0^\\circ<A<90^\\circ$인 $\\angle A$에 대하여 $${trigOf(given, "A")}=${frac(gn, gd)}$일 때, $${trigOf(want, "A")}$의 값을 구하시오.`,
          answer: `$${frac(wn, wd)}$`,
          solution: `$${trigOf(given, "A")}=${frac(gn, gd)}$이므로 ${legText}이다.\n따라서 $${trigOf(want, "A")}=${frac(wn, wd)}$이다.`,
          facts: { p, q, r, given, want, gnum: gn, gden: gd, num: wn, den: wd },
          figureSpec: null,
        };
      }),
  ),

def("삼각비", "04", "직각삼각형의 닮음과 삼각비⑴", SEC.뜻, "응용", (rng) =>
    attempt(120, () => {
      const [p, q, r] = pick(rng, TRIPLES);
      const swap = rng() < 0.5;
      const ab = swap ? q : p;
      const ac = swap ? p : q;
      const which = intBetween(rng, 0, 1);
      const fn = intBetween(rng, 0, 2);
      // $\angle BAH=\angle C$, $\angle CAH=\angle B$ — 닮음이 옮겨 주는 각이다.
      // which 0 은 $\angle C$(대변 $\overline{AB}$), which 1 은 $\angle B$(대변 $\overline{AC}$).
      const opp = which === 0 ? ab : ac;
      const adj = which === 0 ? ac : ab;
      if (fn === 2 && opp >= adj) return null;
      const [num, den] =
        fn === 2 ? red(opp, adj) : red(fn === 0 ? opp : adj, r);
      const same = which === 0 ? `\\angle C` : `\\angle B`;
      const oppName = which === 0 ? `\\overline{AB}` : `\\overline{AC}`;
      const adjName = which === 0 ? `\\overline{AC}` : `\\overline{AB}`;
      const ratio = [
        `\\dfrac{${oppName}}{\\overline{BC}}`,
        `\\dfrac{${adjName}}{\\overline{BC}}`,
        `\\dfrac{${oppName}}{${adjName}}`,
      ][fn]!;
      const angName = which === 0 ? `\\angle BAH` : `\\angle CAH`;
      return {
        content: `$\\angle A=90^\\circ$인 직각삼각형 $ABC$에서 꼭짓점 $A$에서 빗변 $BC$에 내린 수선의 발을 $H$라 하자. $\\overline{AB}=${cm(ab)}$, $\\overline{AC}=${cm(ac)}$이고 $${angName}=x$일 때, $${trigOf(fn, "x")}$의 값을 구하시오.`,
        answer: `$${frac(num, den)}$`,
        solution: `직각삼각형 $ABH$와 직각삼각형 $CBA$는 닮은 도형이므로 $${angName}=${same}$이다.\n피타고라스 정리에서 $\\overline{BC}=\\sqrt{${ab}^2+${ac}^2}=${r}\\,(\\mathrm{cm})$이다.\n따라서 $${trigOf(fn, "x")}=${trigOf(fn, same)}=${ratio}=${frac(num, den)}$이다.`,
        facts: { ab, ac, bc: r, which, fn, num, den },
        figureSpec: figAltitude({
          ab,
          ac,
          dims: { AB: dimCm(ab), AC: dimCm(ac) },
          angBAH: which === 0 ? "x" : undefined,
          angCAH: which === 1 ? "x" : undefined,
        }),
      };
    }),
  ),

def("삼각비", "05", "직각삼각형의 닮음과 삼각비⑵", SEC.뜻, "심화하", (rng) =>
    attempt(120, () => {
      const [p, q, r] = pick(rng, TRIPLES);
      const swap = rng() < 0.5;
      const ah = swap ? q : p;
      const bh = swap ? p : q;
      // 직각삼각형 $ABH$($\angle AHB=90^\circ$)에서 빗변은 $\overline{AB}=r$.
      // $\angle B$ 의 대변은 $\overline{AH}$, $\angle BAH(=\angle C)$ 의 대변은 $\overline{BH}$.
      const which = intBetween(rng, 0, 1);
      const fn = intBetween(rng, 0, 2);
      const opp = which === 0 ? ah : bh;
      const adj = which === 0 ? bh : ah;
      if (fn === 2 && opp >= adj) return null;
      const [num, den] =
        fn === 2 ? red(opp, adj) : red(fn === 0 ? opp : adj, r);
      const target = which === 0 ? `B` : `C`;
      const oppName = which === 0 ? `\\overline{AH}` : `\\overline{BH}`;
      const adjName = which === 0 ? `\\overline{BH}` : `\\overline{AH}`;
      const ratio = [
        `\\dfrac{${oppName}}{\\overline{AB}}`,
        `\\dfrac{${adjName}}{\\overline{AB}}`,
        `\\dfrac{${oppName}}{${adjName}}`,
      ][fn]!;
      const lead =
        which === 0
          ? `직각삼각형 $ABH$에서 $\\angle AHB=90^\\circ$이다.`
          : `직각삼각형 $ABH$와 직각삼각형 $CBA$는 닮은 도형이므로 $\\angle BAH=\\angle C$이다.`;
      const named = which === 0 ? `\\angle B` : `\\angle BAH`;
      return {
        content: `$\\angle A=90^\\circ$인 직각삼각형 $ABC$에서 꼭짓점 $A$에서 빗변 $BC$에 내린 수선의 발을 $H$라 하자. $\\overline{AH}=${cm(ah)}$, $\\overline{BH}=${cm(bh)}$일 때, $${trigOf(fn, target)}$의 값을 구하시오.`,
        answer: `$${frac(num, den)}$`,
        solution: `${lead}\n피타고라스 정리에서 $\\overline{AB}=\\sqrt{${ah}^2+${bh}^2}=${r}\\,(\\mathrm{cm})$이다.\n따라서 $${trigOf(fn, target)}=${trigOf(fn, named)}=${ratio}=${frac(num, den)}$이다.`,
        facts: { ah, bh, ab: r, which, fn, num, den },
        figureSpec: figAltitude({
          ab: r,
          ac: r2((ah * r) / bh),
          dims: { AH: dimCm(ah), BH: dimCm(bh) },
        }),
      };
    }),
  ),

def("삼각비", "08", "의 삼각비의 값", SEC.값, "기본", (rng) =>
    attempt(300, () => {
      const angles = [30, 45, 60] as const;
      const a1 = pick(rng, angles);
      const a2 = pick(rng, angles);
      const f1 = intBetween(rng, 0, 2);
      const f2 = intBetween(rng, 0, 2);
      if (a1 === a2 && f1 === f2) return null;
      const op = intBetween(rng, 0, 3);
      const v1 = exact(f1, a1);
      const v2 = exact(f2, a2);
      if (!v1 || !v2) return null;
      const res = applyOp(op, v1, v2);
      if (!res) return null;
      if (res.r === 1 && res.d > 1 && Math.abs(res.n) >= res.d) return null;
      const expr = `${trigText(f1, a1)} ${OP_TEXT[op]} ${trigText(f2, a2)}`;
      return {
        content: `$${expr}$의 값을 구하시오.`,
        answer: `$${surdText(res)}$`,
        solution: `$${trigText(f1, a1)}=${surdText(v1)}$, $${trigText(f2, a2)}=${surdText(v2)}$이다.\n따라서 $${expr}=${surdText(v1)} ${OP_TEXT[op]} ${surdText(v2)}=${surdText(res)}$이다.`,
        facts: { f1, a1, op, f2, a2, an: res.n, ar: res.r, ad: res.d },
        figureSpec: null,
      };
    }),
  ),

def(
    "삼각비",
    "12",
    "사분원을 이용하여 삼각비의 값 구하기",
    SEC.값,
    "응용",
    (rng) => {
      const ang = intBetween(rng, 25, 65);
      const rad = ang * DEG;
      const s100 = Math.round(Math.sin(rad) * 100);
      const c100 = Math.round(Math.cos(rad) * 100);
      const t100 = Math.round(Math.tan(rad) * 100);
      const mode = intBetween(rng, 0, 4);
      const parts = [[s100], [c100], [t100], [s100, c100], [c100, t100]][mode]!;
      const x100 = parts.reduce((u, v) => u + v, 0);
      const asked = [
        `\\sin ${ang}^\\circ`,
        `\\cos ${ang}^\\circ`,
        `\\tan ${ang}^\\circ`,
        `\\sin ${ang}^\\circ+\\cos ${ang}^\\circ`,
        `\\cos ${ang}^\\circ+\\tan ${ang}^\\circ`,
      ][mode]!;
      const two = (v: number): string => (v / 100).toFixed(2);
      return {
        content: `반지름의 길이가 $1$인 사분원에서 $\\angle AOB=${ang}^\\circ$이다. 점 $B$에서 $\\overline{OA}$에 내린 수선의 발을 $H$라 하고, 점 $A$를 지나고 $\\overline{OA}$에 수직인 직선이 $\\overrightarrow{OB}$와 만나는 점을 $T$라 하자. $\\overline{BH}=${two(s100)}$, $\\overline{OH}=${two(c100)}$, $\\overline{AT}=${two(t100)}$일 때, $${asked}$의 값을 구하시오.`,
        answer: `$${two(x100)}$`,
        solution: `$\\overline{OB}=\\overline{OA}=1$이므로 $\\sin ${ang}^\\circ=\\dfrac{\\overline{BH}}{\\overline{OB}}=\\overline{BH}$, $\\cos ${ang}^\\circ=\\dfrac{\\overline{OH}}{\\overline{OB}}=\\overline{OH}$, $\\tan ${ang}^\\circ=\\dfrac{\\overline{AT}}{\\overline{OA}}=\\overline{AT}$이다.\n따라서 $${asked}=${two(x100)}$이다.`,
        facts: { ang, s100, c100, t100, mode, x100 },
        figureSpec: figQuadrant({ ang }),
      };
    },
  ),

def("삼각비", "14", "삼각비의 값의 대소 관계", SEC.값, "응용", (rng) => {
    // $45^\circ$ 부근은 두 값이 붙어 대소가 «학생이 아는 근거»로 안 갈린다 —
    // 양쪽으로 떼어 놓는다($\cos A$ 와 $\tan A$ 는 $38.17^\circ$ 부근에서 뒤집힌다).
    const ang = rng() < 0.5 ? intBetween(rng, 10, 35) : intBetween(rng, 55, 80);
    const rad = ang * DEG;
    const vals = [Math.sin(rad), Math.cos(rad), Math.tan(rad)];
    const mode = intBetween(rng, 0, 1);
    let best = 0;
    for (let i = 1; i < 3; i += 1) {
      if (mode === 0 ? vals[i]! > vals[best]! : vals[i]! < vals[best]!)
        best = i;
    }
    const word = mode === 0 ? "가장 큰" : "가장 작은";
    const reason =
      ang < 45
        ? `$0^\\circ<A<45^\\circ$이면 $\\sin A<\\tan A<\\cos A$이다.`
        : `$45^\\circ<A<90^\\circ$이면 $\\cos A<\\sin A<\\tan A$이다.`;
    return {
      content: `$\\sin ${ang}^\\circ$, $\\cos ${ang}^\\circ$, $\\tan ${ang}^\\circ$ 중에서 그 값이 ${word} 것을 구하시오.`,
      answer: `$${trigText(best, ang)}$`,
      solution: `${reason}\n$${ang}^\\circ$는 그 범위에 있으므로 ${word} 것은 $${trigText(best, ang)}$이다.`,
      facts: { ang, mode, pick: best },
      figureSpec: null,
    };
  }),

def(
    "삼각비",
    "15",
    "삼각비의 값의 대소 관계를 이용한 식의 계산",
    SEC.값,
    "심화하",
    (rng) => {
      const mode = intBetween(rng, 0, 4);
      const spec = [
        {
          lo: 0,
          hi: 45,
          expr: `\\sqrt{(\\sin A-\\cos A)^2}+\\sqrt{(\\sin A+\\cos A)^2}`,
          c0: 0,
          cs: 0,
          cc: 2,
          ct: 0,
          why: `$0^\\circ<A<45^\\circ$이면 $\\sin A<\\cos A$이므로 $\\sqrt{(\\sin A-\\cos A)^2}=\\cos A-\\sin A$이고, $\\sin A+\\cos A>0$이므로 $\\sqrt{(\\sin A+\\cos A)^2}=\\sin A+\\cos A$이다.`,
        },
        {
          lo: 45,
          hi: 90,
          expr: `\\sqrt{(\\sin A-\\cos A)^2}+\\sqrt{(\\sin A+\\cos A)^2}`,
          c0: 0,
          cs: 2,
          cc: 0,
          ct: 0,
          why: `$45^\\circ<A<90^\\circ$이면 $\\cos A<\\sin A$이므로 $\\sqrt{(\\sin A-\\cos A)^2}=\\sin A-\\cos A$이고, $\\sin A+\\cos A>0$이므로 $\\sqrt{(\\sin A+\\cos A)^2}=\\sin A+\\cos A$이다.`,
        },
        {
          lo: 0,
          hi: 45,
          expr: `\\sqrt{(\\tan A-1)^2}-\\sqrt{(1-\\tan A)^2}`,
          c0: 0,
          cs: 0,
          cc: 0,
          ct: 0,
          why: `$0^\\circ<A<45^\\circ$이면 $\\tan A<1$이므로 $\\sqrt{(\\tan A-1)^2}=1-\\tan A$이고 $\\sqrt{(1-\\tan A)^2}=1-\\tan A$이다.`,
        },
        {
          lo: 0,
          hi: 90,
          expr: `\\sqrt{(1-\\sin A)^2}+\\sqrt{(\\sin A-1)^2}`,
          c0: 2,
          cs: -2,
          cc: 0,
          ct: 0,
          why: `$0^\\circ<A<90^\\circ$이면 $\\sin A<1$이므로 두 근호 안의 식은 모두 $(1-\\sin A)^2$과 같다.`,
        },
        {
          lo: 45,
          hi: 90,
          expr: `\\sqrt{(\\cos A-\\sin A)^2}-\\sqrt{(\\cos A+\\sin A)^2}`,
          c0: 0,
          cs: 0,
          cc: -2,
          ct: 0,
          why: `$45^\\circ<A<90^\\circ$이면 $\\cos A<\\sin A$이므로 $\\sqrt{(\\cos A-\\sin A)^2}=\\sin A-\\cos A$이고, $\\cos A+\\sin A>0$이므로 $\\sqrt{(\\cos A+\\sin A)^2}=\\cos A+\\sin A$이다.`,
        },
      ][mode]!;
      const terms: string[] = [];
      if (spec.c0 !== 0) terms.push(`${spec.c0}`);
      const push = (c: number, t: string): void => {
        if (c === 0) return;
        const mag = Math.abs(c) === 1 ? "" : `${Math.abs(c)}`;
        const sign = c < 0 ? "-" : terms.length > 0 ? "+" : "";
        terms.push(`${sign}${mag}${t}`);
      };
      push(spec.cs, `\\sin A`);
      push(spec.cc, `\\cos A`);
      push(spec.ct, `\\tan A`);
      const ansText = terms.length === 0 ? "0" : terms.join("");
      return {
        content: `$${spec.lo}^\\circ<A<${spec.hi}^\\circ$일 때, $${spec.expr}$을 간단히 하시오.`,
        answer: `$${ansText}$`,
        solution: `${spec.why}\n따라서 $${spec.expr}=${ansText}$이다.`,
        facts: {
          mode,
          lo: spec.lo,
          hi: spec.hi,
          c0: spec.c0,
          cs: spec.cs,
          cc: spec.cc,
          ct: spec.ct,
        },
        figureSpec: null,
      };
    },
  ),

def(
    "삼각비",
    "16",
    "삼각비의 표를 이용하여 삼각비의 값 구하기",
    SEC.값,
    "기본",
    (rng) => {
      const b = intBetween(rng, 30, 58);
      const fn = intBetween(rng, 0, 2);
      const table = [0, 1, 2].map((i) => tableValue(fn, b + i));
      const mode = intBetween(rng, 0, 2);
      const rows = [0, 1, 2]
        .map((i) => `$${trigText(fn, b + i)}=${table[i]!.toFixed(4)}$`)
        .join(", ");
      const head = `삼각비의 표에서 ${rows}이다.`;
      if (mode === 0) {
        return {
          // 소수 넷째 자리까지 적으므로 마지막에 읽는 숫자는 만 배 한 정수의 끝 자리다.
          content: `${head} 이때 $${FN_NAMES[fn]} x=${table[2]!.toFixed(4)}$${eulReul(Math.round(table[2]! * 10000))} 만족시키는 $x$의 크기를 구하시오.`,
          answer: `$${b + 2}^\\circ$`,
          solution: `표에서 값이 $${table[2]!.toFixed(4)}$인 각을 찾으면 $${b + 2}^\\circ$이다.\n따라서 $x=${b + 2}^\\circ$이다.`,
          facts: { b, fn, mode, target: b + 2, val: table[2]! },
          figureSpec: null,
        };
      }
      if (mode === 1) {
        const sum = Number((table[0]! + table[2]!).toFixed(4));
        return {
          content: `${head} 이때 $${trigText(fn, b)}+${trigText(fn, b + 2)}$의 값을 구하시오.`,
          answer: `$${sum.toFixed(4)}$`,
          solution: `표에서 $${trigText(fn, b)}=${table[0]!.toFixed(4)}$, $${trigText(fn, b + 2)}=${table[2]!.toFixed(4)}$이다.\n따라서 구하는 값은 $${table[0]!.toFixed(4)}+${table[2]!.toFixed(4)}=${sum.toFixed(4)}$이다.`,
          facts: { b, fn, mode, target: b, val: sum },
          figureSpec: null,
        };
      }
      // 차 — 큰 값에서 작은 값을 뺀다($\cos$ 는 각이 커질수록 작아진다).
      const hi = fn === 1 ? b : b + 2;
      const lo = fn === 1 ? b + 2 : b;
      const diff = Number((tableValue(fn, hi) - tableValue(fn, lo)).toFixed(4));
      return {
        content: `${head} 이때 $${trigText(fn, hi)}-${trigText(fn, lo)}$의 값을 구하시오.`,
        answer: `$${diff.toFixed(4)}$`,
        solution: `표에서 $${trigText(fn, hi)}=${tableValue(fn, hi).toFixed(4)}$, $${trigText(fn, lo)}=${tableValue(fn, lo).toFixed(4)}$이다.\n따라서 구하는 값은 $${tableValue(fn, hi).toFixed(4)}-${tableValue(fn, lo).toFixed(4)}=${diff.toFixed(4)}$이다.`,
        facts: { b, fn, mode, target: hi, val: diff },
        figureSpec: null,
      };
    },
  ),

def(
    "삼각비",
    "18",
    "의 삼각비의 값을 이용하여 다른 삼각비의 값 구하기",
    SEC.값,
    "심화하",
    (rng) => {
      const a = pick(
        rng,
        Array.from({ length: 51 }, (_, i) => i + 20).filter((v) => v !== 45),
      );
      const sv = tableValue(0, a);
      const cv = tableValue(1, a);
      const mode = intBetween(rng, 0, 2);
      const co = 90 - a;
      const asked = [
        `\\cos ${co}^\\circ`,
        `\\sin ${co}^\\circ`,
        `\\sin ${co}^\\circ+\\cos ${co}^\\circ`,
      ][mode]!;
      const val = [sv, cv, Number((sv + cv).toFixed(4))][mode]!;
      const candidates = [
        [cv, 1 - sv, 1 - cv, 1, (sv + cv) / 2, Math.abs(sv - cv), sv * cv],
        [sv, 1 - cv, 1 - sv, 1, (sv + cv) / 2, Math.abs(sv - cv), sv * cv],
        [sv, cv, Math.abs(sv - cv), 1, 2 * sv, 2 * cv],
      ][mode]!;
      // 실제 보기에 적는 네 자리 값으로 중복을 가른다. 후보 순서대로 골라
      // 난수를 더 쓰지 않고, 모자라면 공용 파생기의 기존 경로를 남긴다.
      const seen = new Set([val.toFixed(4)]);
      const distractors: string[] = [];
      for (const candidate of candidates) {
        const shown = candidate.toFixed(4);
        if (Number(shown) <= 0 || seen.has(shown)) continue;
        seen.add(shown);
        distractors.push(`$${shown}$`);
        if (distractors.length === 4) break;
      }
      const why = [
        `$\\cos ${co}^\\circ=\\cos(90^\\circ-${a}^\\circ)=\\sin ${a}^\\circ$이다.`,
        `$\\sin ${co}^\\circ=\\sin(90^\\circ-${a}^\\circ)=\\cos ${a}^\\circ$이다.`,
        `$\\sin ${co}^\\circ=\\cos ${a}^\\circ$이고 $\\cos ${co}^\\circ=\\sin ${a}^\\circ$이다.`,
      ][mode]!;
      return {
        content: `삼각비의 표에서 $\\sin ${a}^\\circ=${sv.toFixed(4)}$, $\\cos ${a}^\\circ=${cv.toFixed(4)}$일 때, $${asked}$의 값을 구하시오.`,
        answer: `$${val.toFixed(4)}$`,
        solution: `${why}\n따라서 $${asked}=${val.toFixed(4)}$이다.`,
        facts: { a, sv, cv, mode, val },
        figureSpec: null,
        ...(distractors.length === 4 ? { distractors } : {}),
      };
    },
  ),

  /**
   * **19 — 여각의 삼각비** (2026-08-29 추가, RPM 삼각비 01~18 다음 번호).
   *
   * 기존 일곱(뜻)의 시작과 끝:
   *   01 두 변 → 삼각비 · 02 삼각비+한 변 → 다른 변
   *   **03 한 삼각비 → 같은 각의 다른 삼각비** · 04·05 수선의 발 → 삼각비
   *   06 직선의 기울기 → 삼각비 · 07 직육면체 대각선 → 삼각비
   *
   * **「한 각의 삼각비 → 여각의 삼각비」가 없다.** 03 은 같은 각에서 끝나고,
   * 08~18(삼각비의 값)의 18 은 **표의 특수각**에서 여각을 쓴다. 뜻 단원에서
   * 비로 정의한 일반각의 여각이 비어 있었다.
   *
   * 답이 발문과 같은 수가 되는 자리(예: $\\sin A$ → $\\cos(90^\\circ-A)$)는
   * 항등식이 답을 말해 버리므로 버린다.
   */

def(
    "삼각비",
    "20",
    "두 삼각비의 값을 이용한 식의 계산",
    SEC.뜻,
    "연산",
    (rng) =>
      attempt(120, () => {
        const [p0, q0, r0] = pick(rng, TRIPLES);
        const g0 = gcd(gcd(p0, q0), r0);
        const u = p0 / g0;
        const v = q0 / g0;
        const w = r0 / g0;
        if (u >= v) return null;
        const mode = intBetween(rng, 0, 2);
        const sinTex = frac(u, w);
        const cosTex = frac(v, w);
        const [num, den] =
          mode === 0
            ? red(u * v, w * w)
            : mode === 1
              ? red(u, v)
              : red(u * u, v * w);
        if (num >= den) return null;
        // 밑단이므로 답이 커지면 안 된다 — $\dfrac{420}{1369}$ 은 연산이 아니다.
        if (den > 300) return null;
        const asked =
          mode === 0
            ? "\\sin A\\times\\cos A"
            : mode === 1
              ? "\\sin A\\div\\cos A"
              : "\\sin A\\times\\tan A";
        const [tn, td] = red(u, v);
        const work =
          mode === 0
            ? `$${asked}=${sinTex}\\times${cosTex}=${frac(num, den)}$이다.`
            : mode === 1
              ? `$${asked}=${sinTex}\\div${cosTex}=${frac(num, den)}$이다.`
              : `$\\tan A=\\sin A\\div\\cos A=${sinTex}\\div${cosTex}=${frac(tn, td)}$이다.\n` +
                `$${asked}=${sinTex}\\times${frac(tn, td)}=${frac(num, den)}$이다.`;
        return {
          content: `$0^\\circ<A<90^\\circ$인 $\\angle A$에 대하여 $\\sin A=${sinTex}$, $\\cos A=${cosTex}$일 때, $${asked}$의 값을 구하시오.`,
          answer: `$${frac(num, den)}$`,
          solution: `${work}\n따라서 구하는 값은 $${frac(num, den)}$이다.`,
          facts: nums({ u, v, w, mode, num, den }),
          figureSpec: null,
        };
      }),
  ),

  /**
   * **21 — 삼각비를 이용하여 직각삼각형의 넓이 구하기** (기본).
   *
   * 02(삼각비 → 변의 길이)에서 **한 걸음 더** 간다: 구한 변으로 **넓이**를 낸다.
   * 이 소단원의 여덟은 전부 「삼각비의 값」 아니면 「변의 길이」에서 끝났다 —
   * 넓이로 끝나는 자리가 비어 있었다.
   *
   * ⚠️ 「삼각비의 활용」 08(삼각형의 넓이)과 다르다. 그쪽은 $\dfrac12ab\sin C$ 로
   *    **끼인각**을 쓰고, 여기는 직각삼각형에서 두 변을 구해 곱한다. 소단원도 다르다.
   */

def(
    "삼각비의 활용",
    "01",
    "직각삼각형의 변의 길이 구하기",
    SEC.활용,
    "기본",
    (rng) =>
      attempt<Body>(200, () => {
        const theta = pick(rng, [30, 45, 60] as const);
        const g = pick(rng, [4, 6, 8, 10, 12, 16, 20] as const);
        const mode = intBetween(rng, 0, 1);
        const sinT = exact(0, theta)!;
        const cosT = exact(1, theta)!;
        const adj = surdMul(surd(g, 1, 1), cosT);
        const opp = surdMul(surd(g, 1, 1), sinT);
        if (mode === 0) {
          // (넓이) $=\dfrac{1}{2}\times\overline{AB}\times\overline{BC}$
          const area = surdMul(surdMul(adj, opp), surd(1, 1, 2));
          if (area.d !== 1) return null;
          return {
            content: `직각삼각형 $ABC$에서 $\\angle B=90^\\circ$, $\\angle A=${theta}^\\circ$이고 $\\overline{AC}=${cm(g)}$일 때, 직각삼각형 $ABC$의 넓이를 구하시오.`,
            answer: `$${cm2(surdText(area))}$`,
            solution: `$\\overline{AB}=${g}\\times\\cos ${theta}^\\circ=${surdText(adj)}\\,(\\mathrm{cm})$, $\\overline{BC}=${g}\\times\\sin ${theta}^\\circ=${surdText(opp)}\\,(\\mathrm{cm})$이다.\n따라서 (넓이)$=\\dfrac{1}{2}\\times${surdText(adj)}\\times${surdText(opp)}=${surdText(area)}\\,(\\mathrm{cm}^2)$이다.`,
            facts: nums({ theta, given: g, mode, an: area.n, ar: area.r }),
            figureSpec: figRight({
              vert: surdValue(adj),
              horz: surdValue(opp),
              angA: `${theta}°`,
              dims: { CA: dimCm(g) },
            }),
          };
        }
        // 둘레 — 유리항과 무리항을 따로 모은다($45^\circ$ 는 둘 다 $\sqrt{2}$ 라 합쳐진다).
        let c0 = g;
        let irr: Surd = { n: 0, r: 1, d: 1 };
        for (const s of [adj, opp]) {
          if (s.r === 1) {
            c0 += s.n / s.d;
            continue;
          }
          const t = surdAdd(irr, s);
          if (!t) return null;
          irr = t;
        }
        if (!Number.isInteger(c0)) return null;
        if (irr.n === 0 || irr.d !== 1) return null;
        return {
          content: `직각삼각형 $ABC$에서 $\\angle B=90^\\circ$, $\\angle A=${theta}^\\circ$이고 $\\overline{AC}=${cm(g)}$일 때, 직각삼각형 $ABC$의 둘레의 길이를 구하시오.`,
          answer: `$${lenText(c0, irr.n, irr.r, "cm")}$`,
          solution: `$\\overline{AB}=${g}\\times\\cos ${theta}^\\circ=${surdText(adj)}\\,(\\mathrm{cm})$, $\\overline{BC}=${g}\\times\\sin ${theta}^\\circ=${surdText(opp)}\\,(\\mathrm{cm})$이다.\n따라서 (둘레)$=${g}+${surdText(adj)}+${surdText(opp)}=${binomText(c0, irr.n, irr.r)}\\,(\\mathrm{cm})$이다.`,
          facts: nums({ theta, given: g, mode, c0, c1: irr.n, root: irr.r }),
          figureSpec: figRight({
            vert: surdValue(adj),
            horz: surdValue(opp),
            angA: `${theta}°`,
            dims: { CA: dimCm(g) },
          }),
        };
      }),
  ),

def(
    "삼각비의 활용",
    "02",
    "입체도형에서 직각삼각형의 변의 길이의 활용",
    SEC.활용,
    "응용",
    (rng) =>
      attempt(200, () => {
        const theta = pick(rng, [30, 45, 60] as const);
        const mode = intBetween(rng, 0, 2);
        const base = pick(rng, [3, 4, 6, 8, 9, 12] as const);
        const tanT = exact(2, theta)!;
        const cosT = exact(1, theta)!;
        const bs = surd(base, 1, 1);
        const res = mode === 1 ? surdDiv(bs, cosT) : surdMul(bs, tanT);
        if (res.d !== 1 || res.n > 90) return null;
        const scene = [
          {
            content: `밑면이 한 변의 길이가 $${cm(2 * base)}$인 정사각형이고 옆면과 밑면이 이루는 각의 크기가 $${theta}^\\circ$인 정사각뿔이 있다. 이 정사각뿔의 높이를 구하시오.`,
            solution: `밑면의 한 변의 중점과 밑면의 중심 사이의 거리는 $${base}\\,\\mathrm{cm}$이다.\n높이를 $h\\,\\mathrm{cm}$라 하면 $\\tan ${theta}^\\circ=\\dfrac{h}{${base}}$이다.\n따라서 $h=${base}\\times${surdText(tanT)}=${surdText(res)}$이므로 높이는 $${cm(surdText(res))}$이다.`,
          },
          {
            content: `밑면의 반지름의 길이가 $${cm(base)}$이고 모선과 밑면이 이루는 각의 크기가 $${theta}^\\circ$인 원뿔이 있다. 이 원뿔의 모선의 길이를 구하시오.`,
            solution: `모선의 길이를 $l\\,\\mathrm{cm}$라 하면 밑면의 반지름과 모선이 이루는 직각삼각형에서 $\\cos ${theta}^\\circ=\\dfrac{${base}}{l}$이다.\n따라서 $l=\\dfrac{${base}}{${surdText(cosT)}}=${surdText(res)}$이므로 모선의 길이는 $${cm(surdText(res))}$이다.`,
          },
          {
            content: `밑면의 반지름의 길이가 $${cm(base)}$이고 모선과 밑면이 이루는 각의 크기가 $${theta}^\\circ$인 원뿔이 있다. 이 원뿔의 높이를 구하시오.`,
            solution: `높이를 $h\\,\\mathrm{cm}$라 하면 밑면의 반지름과 높이가 이루는 직각삼각형에서 $\\tan ${theta}^\\circ=\\dfrac{h}{${base}}$이다.\n따라서 $h=${base}\\times${surdText(tanT)}=${surdText(res)}$이므로 높이는 $${cm(surdText(res))}$이다.`,
          },
        ][mode]!;
        return {
          content: scene.content,
          answer: `$${cm(surdText(res))}$`,
          solution: scene.solution,
          facts: { theta, base, mode, an: res.n, ar: res.r },
          figureSpec: null,
        };
      }),
  ),

def(
    "삼각비의 활용",
    "03",
    "실생활에서 직각삼각형의 변의 길이의 활용 ⑴",
    SEC.활용,
    "응용",
    (rng) =>
      attempt(200, () => {
        const theta = pick(rng, [30, 45, 60] as const);
        const d = pick(rng, [6, 8, 9, 10, 12, 15, 18, 20] as const);
        const mode = intBetween(rng, 0, 2);
        const sinT = exact(0, theta)!;
        const cosT = exact(1, theta)!;
        const tanT = exact(2, theta)!;
        const ds = surd(d, 1, 1);
        const res =
          mode === 0
            ? surdMul(ds, tanT)
            : mode === 1
              ? surdDiv(ds, cosT)
              : surdMul(ds, sinT);
        if (res.d !== 1 || res.n > 90) return null;
        const height =
          mode === 2
            ? surdValue(res)
            : mode === 0
              ? surdValue(res)
              : d * Math.tan(theta * DEG);
        const ground = mode === 2 ? d * Math.cos(theta * DEG) : d;
        const scene = [
          {
            content: `지면에 수직으로 서 있는 나무의 밑동에서 $${d}\\,\\mathrm{m}$ 떨어진 지점에서 나무의 꼭대기를 올려본각의 크기가 $${theta}^\\circ$이었다. 이 나무의 높이를 구하시오.`,
            solution: `나무의 높이를 $h\\,\\mathrm{m}$라 하면 $\\tan ${theta}^\\circ=\\dfrac{h}{${d}}$이다.\n따라서 $h=${d}\\times\\tan ${theta}^\\circ=${surdText(res)}$이므로 나무의 높이는 $${surdText(res)}\\,\\mathrm{m}$이다.`,
            dimKey: "BC",
          },
          {
            content: `벽에 사다리를 기대어 놓았더니 사다리가 지면과 이루는 각의 크기가 $${theta}^\\circ$이고, 사다리의 아래 끝이 벽에서 $${d}\\,\\mathrm{m}$ 떨어져 있었다. 이 사다리의 길이를 구하시오.`,
            solution: `사다리의 길이를 $l\\,\\mathrm{m}$라 하면 $\\cos ${theta}^\\circ=\\dfrac{${d}}{l}$이다.\n따라서 $l=\\dfrac{${d}}{${surdText(cosT)}}=${surdText(res)}$이므로 사다리의 길이는 $${surdText(res)}\\,\\mathrm{m}$이다.`,
            dimKey: "BC",
          },
          {
            content: `길이가 $${d}\\,\\mathrm{m}$인 실을 모두 풀어 연을 날렸더니 실이 지면과 이루는 각의 크기가 $${theta}^\\circ$이었다. 실이 팽팽하다고 할 때, 지면에서 연까지의 높이를 구하시오.`,
            solution: `연까지의 높이를 $h\\,\\mathrm{m}$라 하면 $\\sin ${theta}^\\circ=\\dfrac{h}{${d}}$이다.\n따라서 $h=${d}\\times\\sin ${theta}^\\circ=${surdText(res)}$이므로 연까지의 높이는 $${surdText(res)}\\,\\mathrm{m}$이다.`,
            dimKey: "CA",
          },
        ][mode]!;
        return {
          content: scene.content,
          answer: `$${surdText(res)}\\,\\mathrm{m}$`,
          solution: scene.solution,
          facts: { theta, d, mode, an: res.n, ar: res.r },
          figureSpec: figRight({
            vert: r2(height),
            horz: r2(ground),
            angC: `${theta}°`,
            dims: { [scene.dimKey]: `${d} m` },
          }),
        };
      }),
  ),

def(
    "삼각비의 활용",
    "05",
    "일반 삼각형의 변의 길이 구하기 한 변의 길이와 그 양 끝 각의 크기를 아는 경우",
    SEC.활용,
    "응용",
    (rng) => {
      const k = intBetween(rng, 1, 6);
      const cfg = pick(rng, [
        // $[\angle B, \angle C]$ 와 $\overline{BC}=k(c_0+c_1\sqrt{root})$,
        // 그때의 $\overline{AB}=k\cdot abC\sqrt{abR}$, $\overline{AC}=k\cdot acC\sqrt{acR}$.
        {
          id: 0,
          b: 30,
          c: 45,
          c0: 1,
          c1: 1,
          root: 3,
          hC: 1,
          abC: 2,
          abR: 1,
          acC: 1,
          acR: 2,
        },
        {
          id: 1,
          b: 45,
          c: 60,
          c0: 3,
          c1: 1,
          root: 3,
          hC: 3,
          abC: 3,
          abR: 2,
          acC: 2,
          acR: 3,
        },
        {
          id: 2,
          b: 30,
          c: 60,
          c0: 0,
          c1: 4,
          root: 3,
          hC: 3,
          abC: 6,
          abR: 1,
          acC: 2,
          acR: 3,
        },
        {
          id: 3,
          b: 45,
          c: 45,
          c0: 2,
          c1: 0,
          root: 1,
          hC: 1,
          abC: 1,
          abR: 2,
          acC: 1,
          acR: 2,
        },
      ] as const);
      const ask = intBetween(rng, 0, 1);
      const bcC0 = cfg.c0 * k;
      const bcC1 = cfg.c1 * k;
      const bcText = binomText(bcC0, bcC1, cfg.root);
      const bcVal = bcC0 + bcC1 * Math.sqrt(cfg.root);
      const res = surd(
        (ask === 0 ? cfg.abC : cfg.acC) * k,
        ask === 0 ? cfg.abR : cfg.acR,
        1,
      );
      const angA = 180 - cfg.b - cfg.c;
      const askName = ask === 0 ? `\\overline{AB}` : `\\overline{AC}`;
      // 직각삼각형 $ABH$ 에서 \sin B = AH/AB 이므로 구하는 변은
      // «높이 ÷ 그 각의 sin» 이다. `hVal` 은 그 높이(정수).
      const nearAng = ask === 0 ? cfg.b : cfg.c;
      const hVal = cfg.hC * k;
      const paren = bcC0 !== 0 && bcC1 !== 0 ? `(${bcText})` : bcText;
      return {
